INSERT INTO public.clients (    created_at,    user_telegram_id,    first_name,    last_name,    last_message_at)WITH client_stats AS (    SELECT        messanger_user_id,        MIN(created_at) AS first_message_at,        MAX(created_at) AS last_message_at    FROM public.messages    WHERE messanger_user_id IS NOT NULL    GROUP BY messanger_user_id),     first_messages AS (         SELECT DISTINCT ON (messanger_user_id)    messanger_user_id,    TRIM(author) AS authorFROM public.messagesWHERE messanger_user_id IS NOT NULLORDER BY messanger_user_id, created_at ASC, id ASC    )SELECT    cs.first_message_at,    cs.messanger_user_id,    -- First name    CASE        WHEN fm.author IS NULL OR fm.author = '' THEN NULL        ELSE split_part(fm.author, ' ', 1)        END AS first_name,    -- Last name    CASE        WHEN fm.author IS NULL OR fm.author = '' THEN NULL        WHEN POSITION(' ' IN fm.author) = 0 THEN NULL        ELSE TRIM(                SUBSTRING(                        fm.author                        FROM POSITION(' ' IN fm.author) + 1                )             )        END AS last_name,    cs.last_message_at::timestampFROM client_stats cs         JOIN first_messages fm              ON fm.messanger_user_id = cs.messanger_user_id;